/* ==========================================================================
   e26-06 Medata SingleMA｜Shiny 元件對應樣式 app_20261115_CSX.css
   只負責把 Shiny 產生的標記套上 theme_v3_20261115_CSX.css 的外觀。
   規則同 theme_v3：文字色只用 theme_v3 登錄過的 --hdh-* 文字變數；金色 --hdh-gold 只當框線；
   字級只用 --hdh-fs-* 五階（最小 14px）；圖片 height:auto，不加 opacity／filter／transform。
   ========================================================================== */

body.hdh-app { padding: 0; }

/* 步驟 1：Shiny radioButtons → 選項卡（對應 theme_v3 .hdh-choice）*/
.hdh-typechoice .shiny-options-group { margin: 0; }
.hdh-typechoice .radio, .hdh-typechoice .form-check { margin: 0; padding: 0; }
.hdh-typechoice .control-label:empty, .hdh-typechoice label.control-label { display: none; }
.hdh-typechoice .shiny-options-group label { display: block; border: 2px solid var(--hdh-line-strong); border-radius: var(--hdh-radius); padding: 10px 12px; margin-bottom: 8px; cursor: pointer; background: var(--hdh-bg); min-height: var(--hdh-tap); color: var(--hdh-ink); font-size: var(--hdh-fs-base); }
.hdh-typechoice input[type="radio"] { accent-color: var(--hdh-red); width: 18px; height: 18px; margin: 0 8px 0 0; vertical-align: -3px; position: static; float: none; }
.hdh-typechoice .shiny-options-group label b { color: var(--hdh-ink); }
.hdh-typechoice .shiny-options-group label .hdh-choice__d { display: block; font-size: var(--hdh-fs-sm); color: var(--hdh-muted); padding-left: 30px; }
.hdh-typechoice .shiny-options-group label:has(input:checked) { border-color: var(--hdh-red); background: var(--hdh-bg-palegold); }
.hdh-typechoice .shiny-options-group label:has(input:checked) .hdh-choice__d { color: var(--hdh-ink); }

/* 表單：Shiny 標籤與輸入 */
.hdh-app .form-group, .hdh-app .shiny-input-container { width: 100% !important; margin-bottom: 4px; }
.hdh-app .control-label, .hdh-app .form-label { display: block; font-size: var(--hdh-fs-base); font-weight: 700; color: var(--hdh-ink); margin: 12px 0 4px; }
.hdh-app textarea.form-control { font-family: var(--hdh-mono); min-height: 150px; font-size: var(--hdh-fs-base); color: var(--hdh-ink); background: var(--hdh-bg); }
.hdh-app .form-control::placeholder { color: var(--hdh-muted); opacity: 1; }
.hdh-app .form-select, .hdh-app select.form-control { color: var(--hdh-ink); background-color: var(--hdh-bg); }
/* 觸控目標至少 44px（--hdh-tap） */
.hdh-app .checkbox label, .hdh-app .form-check-label { font-size: var(--hdh-fs-base); color: var(--hdh-ink); min-height: var(--hdh-tap); display: inline-flex; align-items: center; }
.hdh-app .checkbox input[type="checkbox"] { accent-color: var(--hdh-red); width: 18px; height: 18px; margin-right: 8px; vertical-align: -3px; }
.hdh-app .checkbox, .hdh-app .form-check { margin: 8px 0; }
.hdh-app .is-disabled, .hdh-app .is-disabled label { color: var(--hdh-muted); }
.hdh-app .hdh-sidenote { font-size: var(--hdh-fs-sm); color: var(--hdh-muted); margin: 0 0 8px 26px; }

/* 上傳 CSV：fileInput 外觀比照 .hdh-btn--plain */
.hdh-upload .input-group { flex-wrap: nowrap; }
.hdh-upload .btn-file { font-size: var(--hdh-fs-base); min-height: var(--hdh-tap); border: 2px solid var(--hdh-line-strong); background: var(--hdh-bg); color: var(--hdh-ink); border-radius: var(--hdh-radius); padding: 8px 16px; }
.hdh-upload .btn-file:hover { background: var(--hdh-bg-warm); color: var(--hdh-ink); }
.hdh-upload .form-control[readonly] { display: none; }
.hdh-upload .progress { margin-top: 6px; height: auto; min-height: 24px; background: var(--hdh-bg-warm); font-size: var(--hdh-fs-sm); }
.hdh-upload .progress-bar { background: var(--hdh-red); color: var(--hdh-on-red); font-size: var(--hdh-fs-sm); line-height: 24px; }
.hdh-upload .shiny-input-container { margin: 0; }
.hdh-btnrow > * { flex: 0 1 auto; }
.hdh-app a.hdh-btn, .hdh-app a.hdh-footlink { text-decoration: none; display: inline-flex; align-items: center; gap: 8px; }
.hdh-btn { display: inline-flex; align-items: center; gap: 8px; }

/* 引用視窗的 BibTeX／RIS 下載連結（Shiny actionLink）*/
.hdh-cite__links a { color: var(--hdh-link); display: inline-flex; align-items: center; min-height: var(--hdh-tap); padding: 0 4px; }
.hdh-modal__box:focus { outline: 3px solid var(--hdh-red); outline-offset: 2px; }

/* 結果頁籤：Shiny tabsetPanel（Bootstrap nav-tabs）→ 對應 theme_v3 .hdh-tabs／.hdh-tab */
/* 分頁在窄螢幕自動換行，不藏在畫面外 */
.hdh-results .nav-tabs { flex-wrap: wrap; border-bottom: 2px solid var(--hdh-line); margin-bottom: 12px; }
.hdh-results .nav-tabs .nav-link { white-space: nowrap; color: var(--hdh-ink); font-size: var(--hdh-fs-base); min-height: var(--hdh-tap); border: 0; border-bottom: 3px solid transparent; background: var(--hdh-bg); }
.hdh-results .nav-tabs .nav-link.active { color: var(--hdh-red); border-bottom-color: var(--hdh-red); font-weight: 700; background: var(--hdh-bg); }

/* 圖：固定 700px 寬（--hdh-plot-w），放在可滑動框內，不縮小 */
.hdh-scroll img { display: block; width: var(--hdh-plot-w); max-width: none; height: auto; background: var(--hdh-bg); }
.hdh-scroll .shiny-image-output { width: var(--hdh-plot-w) !important; height: auto !important; }

/* 頁面與狀態切換 */
.hdh-page[hidden], .hdh-state[hidden], .hdh-results-wrap[hidden], .hdh-modal[hidden] { display: none; }

/* Shiny 確認對話框（W08／W09）*/
.modal-body { font-size: var(--hdh-fs-base); color: var(--hdh-ink); }
.modal-footer .btn { font-size: var(--hdh-fs-base); }

/* 主選單在窄螢幕自動換行，不藏在畫面外 */
.hdh-nav { flex-wrap: wrap; overflow-x: visible; }

/* 參考文獻、原始碼清單：長網址可斷行 */
.hdh-refs { padding-left: 20px; margin: 4px 0 12px; }
.hdh-refs li { margin: 4px 0; overflow-wrap: anywhere; }
.hdh-refs a { color: var(--hdh-link); display: inline-flex; align-items: center; min-height: var(--hdh-tap); }
.hdh-app .hdh-help { overflow-wrap: anywhere; }
.hdh-confirm__box { max-width: 480px; }   /* 確認視窗（切換資料類型、清空資料） */
.hdh-confirm__box [data-confirm]:focus { outline: 3px solid var(--hdh-red); outline-offset: 2px; }   /* 確認視窗以滑鼠開啟、焦點由程式移到按鈕時也要看得見焦點框（:focus-visible 不一定成立） */
#hdh-fmt-help { overflow-wrap: anywhere; }   /* 檔案格式說明：範例檔名很長，窄螢幕要能換行 */
/* 資料檢查分頁：控制列可換行；有標記的列加底色（另有「標記」欄文字，不只靠顏色）；分頁列 */
.hdh-dc-ctrl { display: flex; flex-wrap: wrap; gap: 0 16px; align-items: flex-end; }
.hdh-dc-ctrl .form-group { flex: 1 1 160px; min-width: 0; margin-bottom: 8px; }
.hdh-dc-ctrl .form-group input, .hdh-dc-ctrl .form-group select { width: 100%; }
.hdh-table.hdh-dc-table tbody tr:nth-child(even) td { background: var(--hdh-bg); }   /* 不用交替底色，免得和標記底色混淆 */
.hdh-table.hdh-dc-table tbody tr.hdh-dc-flag td { background: var(--hdh-bg-palegold); color: var(--hdh-ink); }
.hdh-table.hdh-dc-table tbody tr.hdh-dc-flag td:first-child { box-shadow: inset 4px 0 0 var(--hdh-warn-fg); }
.hdh-table.hdh-dc-table tbody tr.hdh-dc-flag td:nth-child(4) { color: var(--hdh-warn-fg); font-weight: 700; }   /* 第 4 欄是「標記」 */
.hdh-dc-pager { align-items: center; }
.hdh-dc-info { font-size: var(--hdh-fs-base); }
/* 資料檢查表在窄螢幕：研究名稱與單篇值欄可換行，讓 #、study、單篇值不必左右滑動就看得到 */
@media (max-width: 600px) {
  .hdh-table.hdh-dc-table th, .hdh-table.hdh-dc-table td { padding: 8px 6px; }
  .hdh-table.hdh-dc-table th:nth-child(2), .hdh-table.hdh-dc-table td:nth-child(2) { white-space: normal; min-width: 6.5em; max-width: 8.5em; overflow-wrap: anywhere; }
  .hdh-table.hdh-dc-table th:nth-child(3) { white-space: normal; min-width: 5em; max-width: 6.5em; }
}
/* 資料檢查表：很長、沒有空白的研究名稱在任何寬度都換行，單篇值與標記不會被推到畫面外 */
@media (min-width: 601px) {   /* 窄螢幕另有較窄的設定（上方 max-width: 600px 區塊） */
  .hdh-table.hdh-dc-table th:nth-child(2), .hdh-table.hdh-dc-table td:nth-child(2) { white-space: normal; max-width: 22em; overflow-wrap: anywhere; }
}

// e26-06 Medata SingleMA｜介面行為（外部檔，以便套用不允許行內 script 的 CSP）
// 引用視窗（開啟／Esc／點背景關閉、焦點進出）、複製時同時放入純文字與 HTML、
// 下載訊息（S06／S07）、「開始分析」不停用（沒資料時帶到步驟 ②）。
// 不讀寫瀏覽器儲存空間或 cookie；不連到任何外部網址。
document.documentElement.lang = 'zh-Hant-TW';
document.addEventListener('DOMContentLoaded', function () { document.body.classList.add('hdh-app'); });

// ---- 「開始分析」按下後的進度提示（S6）----
(function(){
  var t = null, t0 = 0;
  window.__hdhStartTimer = function(label){
    var run = document.getElementById('run'); t0 = Date.now(); label = label || '分析中…';
    run.disabled = true; run.textContent = label;
    if (t) clearInterval(t);
    t = setInterval(function(){
      var s = Math.round((Date.now() - t0) / 1000);
      run.textContent = s < 20 ? label + '（已 ' + s + ' 秒）' : label + '（已 ' + s + ' 秒，研究數多或使用 GLMM 時需要較久）';
    }, 1000);
  };
  window.__hdhStopTimer = function(){ if (t) { clearInterval(t); t = null; } };
})();

// ---- 訊息框（只用 textContent，不插入 HTML）----
function hdhNote(boxId, level, text) {
  var box = document.getElementById(boxId); if (!box) return;
  box.innerHTML = '';
  var d = document.createElement('div'); d.className = 'hdh-note hdh-note--' + level;
  d.setAttribute('role', level === 'err' ? 'alert' : 'status');
  var p = document.createElement('p'); p.textContent = text; d.appendChild(p); box.appendChild(d);
}

// ---- 引用視窗：開啟時焦點移入、Tab 不跑出視窗、Esc 與點背景關閉、關閉後焦點回到原按鈕 ----
(function(){
  var opener = null;
  function focusables(root) {
    return Array.prototype.filter.call(root.querySelectorAll('a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])'),
      function (e) { return e.offsetParent !== null; });
  }
  window.hdhOpenModal = function (id, from) {
    var m = document.getElementById(id); if (!m) return;
    opener = from || document.activeElement;
    if (id === 'cite' && window.Shiny && Shiny.setInputValue) {   // cited 日期：使用者當地的「今天」
      var d = new Date(), pad = function (x) { return (x < 10 ? '0' : '') + x; };
      Shiny.setInputValue('cite_date', d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()), {priority: 'event'});
    }
    m.hidden = false;
    if (window.jQuery) window.jQuery(m).trigger('shown');
    var f = focusables(m); (f[0] || m.querySelector('.hdh-modal__box')).focus();
  };
  window.hdhCloseModal = function (id) {
    var m = document.getElementById(id); if (!m || m.hidden) return;
    m.hidden = true;
    // 確認視窗：不是按「繼續」關掉的（取消、Esc、點背景），一律回報「取消」
    if (id === 'hdh-confirm' && m.dataset.cancelId && window.Shiny && Shiny.setInputValue)
      Shiny.setInputValue(m.dataset.cancelId, Date.now(), {priority: 'event'});
    if (id === 'hdh-confirm') { delete m.dataset.okId; delete m.dataset.cancelId; }
    if (opener && document.body.contains(opener)) opener.focus();
    opener = null;
  };
  document.addEventListener('click', function (ev) {
    var o = ev.target.closest('[data-open]'); if (o) { ev.preventDefault(); window.hdhOpenModal(o.getAttribute('data-open'), o); return; }
    var c = ev.target.closest('[data-close]'); if (c) { window.hdhCloseModal(c.getAttribute('data-close')); return; }
    var k = ev.target.closest('[data-confirm]');
    if (k) {
      var cm = document.getElementById('hdh-confirm');
      if (k.getAttribute('data-confirm') === 'ok' && cm.dataset.okId && window.Shiny) {
        var okId = cm.dataset.okId; delete cm.dataset.cancelId;   // 按「繼續」：不送取消
        Shiny.setInputValue(okId, Date.now(), {priority: 'event'});
      }
      window.hdhCloseModal('hdh-confirm'); return;
    }
    if (ev.target.classList && ev.target.classList.contains('hdh-modal')) window.hdhCloseModal(ev.target.id);   // 點深色背景
  });
  document.addEventListener('keydown', function (ev) {
    var m = document.querySelector('.hdh-modal:not([hidden])'); if (!m) return;
    if (ev.key === 'Escape') { ev.preventDefault(); window.hdhCloseModal(m.id); return; }
    if (ev.key === 'Tab') {
      var f = focusables(m); if (!f.length) return;
      var first = f[0], last = f[f.length - 1];
      if (ev.shiftKey && document.activeElement === first) { ev.preventDefault(); last.focus(); }
      else if (!ev.shiftKey && document.activeElement === last) { ev.preventDefault(); first.focus(); }
    }
  });
})();

// ---- 複製：data-rich="1" 時同時放入 text/plain 與 text/html（貼到 Word 時標題保留斜體）----
document.addEventListener('click', function (ev) {
  var b = ev.target.closest('[data-copy]'); if (!b) return;
  var el = document.getElementById(b.getAttribute('data-copy')); if (!el) return;
  var txt = el.innerText, html = el.innerHTML, old = b.textContent, rich = b.getAttribute('data-rich') === '1';
  var done = function () { b.textContent = '已複製'; setTimeout(function () { b.textContent = old; }, 1500); };
  var fallback = function () {   // 不支援 Clipboard API 時：選取元素再複製（瀏覽器會一併放入 HTML 與純文字）
    var r = document.createRange(); r.selectNodeContents(el);
    var s = window.getSelection(); s.removeAllRanges(); s.addRange(r);
    try { document.execCommand('copy'); } catch (e) {}
    s.removeAllRanges(); done();
  };
  if (navigator.clipboard && window.isSecureContext) {
    if (rich && window.ClipboardItem) {
      var item = new ClipboardItem({ 'text/plain': new Blob([txt], { type: 'text/plain' }),
                                     'text/html': new Blob([html], { type: 'text/html' }) });
      navigator.clipboard.write([item]).then(done, fallback);
    } else navigator.clipboard.writeText(txt).then(done, fallback);
  } else fallback();
});

// ---- 主選單切頁（主選單與「帶到步驟 ②」共用）、開始分析 ----
function showPage(id) {
  document.querySelectorAll('.hdh-nav__btn').forEach(function (b) { b.setAttribute('aria-selected', b.getAttribute('data-page') === id ? 'true' : 'false'); });
  document.querySelectorAll('.hdh-page').forEach(function (p) {
    p.hidden = (p.id !== id);
    if (!p.hidden && window.jQuery) window.jQuery(p).trigger('shown');   // 讓 Shiny 重新計算這一頁的輸出
  });
}
(function(){
  document.addEventListener('DOMContentLoaded', function(){
    document.querySelectorAll('.hdh-nav__btn').forEach(function (b) {
      b.addEventListener('click', function () { showPage(b.getAttribute('data-page')); window.scrollTo(0, 0); });
    });
    var run = document.getElementById('run');
    run.addEventListener('click', function(){ if (!run.disabled) window.__hdhStartTimer(); });
    // 載入示範資料：按下就顯示進度（伺服器端分析完成後由 hdh-run 訊息換回）
    ['load_demo', 'load_demo2'].forEach(function (id) {
      var b = document.getElementById(id);
      if (b) b.addEventListener('click', function () { window.__hdhStartTimer('載入示範資料並分析中…'); });
    });
    // 授權檔連結：app 在 iframe 內，改指向網站根目錄下的 legal/
    var base = (function () { try { return window.parent.location.href; } catch (e) { return document.baseURI; } })();
    document.querySelectorAll('a[data-legal]').forEach(function (a) {
      try { a.href = new URL('legal/' + a.getAttribute('data-legal'), base).href; } catch (e) {}
    });
  });
  $(document).on('shiny:connected', function(){
    Shiny.addCustomMessageHandler('hdh-run', function(m){
      window.__hdhStopTimer();
      var run = document.getElementById('run'); run.disabled = !!m.disabled; run.textContent = m.label;
    });
    Shiny.addCustomMessageHandler('hdh-disable', function(m){
      m.ids.forEach(function(id){
        var el = document.getElementById(id); if (!el) return;
        el.disabled = !!m.disabled;
        var box = el.closest('.form-group, .shiny-input-container, .checkbox');
        if (box) box.classList.toggle('is-disabled', !!m.disabled);
      });
    });
    // 下載：成功訊息在觸發下載之後才寫，失敗訊息寫在 catch；都寫到觸發下載的那一個分頁（m.box）
    var DL_ERR = '檔案沒有下載成功，請再按一次。';
    Shiny.addCustomMessageHandler('hdh-download', function(m){
      try {
        var bin = atob(m.b64), u8 = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
        var url = URL.createObjectURL(new Blob([u8], {type: m.mime}));
        var a = document.createElement('a'); a.href = url; a.download = m.name;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout(function(){ URL.revokeObjectURL(url); }, 10000);
        if (m.box && m.ok) hdhNote(m.box, 'ok', m.ok);
      } catch (e) { if (m.box) hdhNote(m.box, 'err', DL_ERR); }   // 每種下載都指定了看得見的位置（範本：步驟 2；引用檔：引用視窗；CSV：森林圖分頁）
    });
    Shiny.addCustomMessageHandler('hdh-dlerr', function(m){ hdhNote(m.box, 'err', DL_ERR); });
    // 確認視窗（取代 Shiny 的 modalDialog：那個會插入行內 script，被 CSP 擋下）
    Shiny.addCustomMessageHandler('hdh-confirm', function(m){
      var cm = document.getElementById('hdh-confirm'); if (!cm) return;
      document.getElementById('hdh-confirm-text').textContent = m.text;
      cm.querySelector('[data-confirm="ok"]').textContent = m.ok;
      cm.dataset.okId = m.okId; cm.dataset.cancelId = m.cancelId;
      window.hdhOpenModal('hdh-confirm');
      cm.querySelector('[data-confirm="cancel"]').focus();   // 預設焦點在「取消」：按 Enter 不會直接清空或切換
    });
    Shiny.addCustomMessageHandler('hdh-dlclear', function(m){
      m.ids.forEach(function(id){ var b = document.getElementById(id); if (b) b.innerHTML = ''; });
    });
    Shiny.addCustomMessageHandler('hdh-goto', function(m){
      var el = document.getElementById(m.id); if (!el) return;
      showPage('pg-run');
      el.scrollIntoView({behavior: 'smooth', block: 'start'});
      var t = document.getElementById('paste'); if (t) t.focus({preventScroll: true});
    });
    $(document).on('shiny:inputchanged', function (ev) {
      if (ev.name !== 'upload') return;
      var set = function () { var bar = document.querySelector('#upload_progress .progress-bar'); if (bar) bar.textContent = '上傳完成'; };
      set(); setTimeout(set, 0); setTimeout(set, 300);
    });
    Shiny.addCustomMessageHandler('hdh-results', function(m){
      var w = document.getElementById('results-wrap'), p = document.getElementById('results-placeholder');
      if (w) w.hidden = !m.show; if (p) p.hidden = !!m.show;
      $(w).trigger('shown');
      if (m.show && m.scroll && window.innerWidth <= 768) {
        var h = document.getElementById('results-title'); if (h) h.scrollIntoView({behavior: 'smooth', block: 'start'});
      }
    });
  });
})();

/* ==========================================================================
   Medata SingleMA（e26-06 單組統合分析工具）｜匯東華品牌樣式 v3
   theme_v3_20261115_CSX.css　—　延續 theme_v2（v1、v2 保留不覆蓋）
   v3 相對 v2：拿掉 CSS 疊加浮水印的兩條規則，圖改為直接顯示產圖端輸出；新增 LINE QR 區塊。

   色彩來源（匯東華品牌色票）：
     T = 匯東華_共同品牌tokens_2026.07.26v1.json 的 colors.functional
     S = 匯東華品牌主色（優先）
     A = 本工具新增的狀態色（品牌來源沒有對應值）
   每個變數後面都標了來源。

   用法（Shiny / bslib, Bootstrap 5）：
     theme <- bslib::bs_theme(version = 5, primary = "#B82226", bg = "#FFFFFF", fg = "#2D2D2D",
                base_font = bslib::font_collection("Microsoft JhengHei", "PMingLiU",
                                                   "Noto Sans TC", "sans-serif"))
     再以 tags$link(rel = "stylesheet", href = "theme_v3_20261115_CSX.css") 載入本檔。

   規則：
     1. 文字色一律用 --hdh-* 變數，不得直接寫色碼。
     2. --hdh-gold（#C4A46D）僅供框線與裝飾，禁止用於 color。
        --hdh-gold-deep（#8B6914）可當文字，但只用於 16px 以上的粗體短句（標語、小標籤），
        且只放在白、米白、淡金底上（量測 4.71–5.09，餘裕小）。
     3. 字級只用 --hdh-fs-* 五階，最小 14px。
     4. 每組「文字色／背景色」登錄於 contrast_check_v3_20261115_CSX.py 的 PAIRS，
        改色後必須重跑（exit 0 才可交付）。
     5. 品牌圖檔（Logo、曇月靈）、QR code 與森林圖只可等比例縮放：
        寬度由 CSS 指定、height 一律 auto；不得加 opacity、filter、transform。
        浮水印不在 CSS 處理：由產圖端把建置時產生的不透明衍生檔畫進「分享用」圖的留白區。
     6. 不載入任何外部字型或 CDN。
