:root {
  /* ---- 品牌色 ---- */
  --hdh-red: #B82226;             /* T brand_red */
  --hdh-red-deep: #8A1A1D;        /* S 深紅：hover、錯誤文字、小標 */
  --hdh-gold: #C4A46D;            /* T brand_gold：僅裝飾，不得當文字色 */
  --hdh-gold-deep: #8B6914;       /* T deep_gold／S：標語、小標籤（粗體 >=16px） */

  /* ---- 文字色 ---- */
  --hdh-ink: #2D2D2D;             /* T text_primary */
  --hdh-muted: #595959;           /* A：取代 T text_secondary #666666（白底對比較高） */
  --hdh-on-red: #FFFFFF;          /* T white：紅底、深紅底上的文字 */
  --hdh-link: #B82226;            /* T brand_red */
  --hdh-link-hover: #8A1A1D;      /* S */

  /* ---- 背景色 ---- */
  --hdh-bg: #FFFFFF;              /* T white：卡片 */
  --hdh-bg-page: #FDF8F3;         /* S 品牌背景色：頁面底 */
  --hdh-bg-warm: #F8F6F0;         /* T background_warm：教學框、程式碼、表格交替列 */
  --hdh-bg-palegold: #FFF8EA;     /* T pale_gold：警告、個資提醒列、已選項目 */
  --hdh-bg-palered: #FCEBEC;      /* T pale_red：錯誤 */
  --hdh-disabled-bg: #E0E0E0;     /* T border：停用按鈕底 */

  /* ---- 狀態色 ---- */
  --hdh-ok-fg: #1E5631;    --hdh-ok-bg: #EAF4EC;       /* A */
  --hdh-warn-fg: #6B4200;                              /* A：配 --hdh-bg-palegold */
  --hdh-err-fg: #8A1A1D;                               /* S：配 --hdh-bg-palered */

  /* ---- 頁尾 ---- */
  --hdh-foot-bg: #2D2D2D;         /* T text_primary 當深色底 */
  --hdh-foot-fg: #FFFFFF;
  --hdh-foot-muted: #E0E0E0;      /* T border */

  /* ---- 線條（非文字）---- */
  --hdh-line: #E0E0E0;            /* T border：表格格線 */
  --hdh-line-strong: #857D70;     /* A：輸入框外框，需 >=3:1 */

  /* ---- 字級（五階，最小 14px）---- */
  --hdh-fs-sm: 14px;
  --hdh-fs-base: 16px;
  --hdh-fs-h3: 18px;
  --hdh-fs-h2: 22px;
  --hdh-fs-h1: 26px;

  --hdh-font: "Microsoft JhengHei", "微軟正黑體", "PMingLiU", "Noto Sans TC", "PingFang TC", sans-serif;
  --hdh-font-latin: Arial, Helvetica, "Microsoft JhengHei", sans-serif;
  --hdh-mono: Consolas, "Cascadia Mono", Menlo, monospace;
  --hdh-radius: 8px;
  --hdh-tap: 44px;
  --hdh-plot-w: 700px;            /* 森林圖顯示寬度（PNG 以 2 倍像素繪製） */

  /* ---- 對應 Bootstrap 5 變數 ---- */
  --bs-primary: #B82226;
  --bs-primary-rgb: 184, 34, 38;
  --bs-body-color: #2D2D2D;
  --bs-body-color-rgb: 45, 45, 45;
  --bs-body-bg: #FDF8F3;
  --bs-body-bg-rgb: 253, 248, 243;
  --bs-body-font-family: var(--hdh-font);
  --bs-body-font-size: 16px;
  --bs-body-line-height: 1.7;
  --bs-secondary-color: #595959;
  --bs-link-color: #B82226;
  --bs-link-color-rgb: 184, 34, 38;
  --bs-link-hover-color: #8A1A1D;
  --bs-link-hover-color-rgb: 138, 26, 29;
  --bs-border-color: #E0E0E0;
  --bs-border-radius: 8px;
  --bs-focus-ring-color: rgba(184, 34, 38, 0.35);
}

/* ---- Bootstrap 元件覆寫（bslib 內亦生效）---- */
.btn-primary {
  --bs-btn-color: var(--hdh-on-red);
  --bs-btn-bg: var(--hdh-red);
  --bs-btn-border-color: var(--hdh-red);
  --bs-btn-hover-color: var(--hdh-on-red);
  --bs-btn-hover-bg: var(--hdh-red-deep);
  --bs-btn-hover-border-color: var(--hdh-red-deep);
  --bs-btn-active-color: var(--hdh-on-red);
  --bs-btn-active-bg: var(--hdh-red-deep);
  --bs-btn-active-border-color: var(--hdh-red-deep);
  --bs-btn-disabled-color: var(--hdh-muted);
