.btn { --bs-btn-font-size: var(--hdh-fs-base); min-height: var(--hdh-tap); }
.card { --bs-card-bg: var(--hdh-bg); --bs-card-border-color: var(--hdh-gold); }
.form-control, .form-select { font-size: var(--hdh-fs-base); min-height: var(--hdh-tap); border-color: var(--hdh-line-strong); }
.form-control:focus, .form-select:focus { border-color: var(--hdh-red); box-shadow: 0 0 0 3px var(--bs-focus-ring-color); }
.form-check-input:checked { background-color: var(--hdh-red); border-color: var(--hdh-red); }
.form-text, .help-block { font-size: var(--hdh-fs-sm); color: var(--hdh-muted); }
.nav-link { --bs-nav-link-color: var(--hdh-ink); --bs-nav-link-hover-color: var(--hdh-red-deep); font-size: var(--hdh-fs-base); }
.nav-tabs .nav-link.active, .nav-underline .nav-link.active, .navbar-nav .nav-link.active {
  color: var(--hdh-red); border-bottom-color: var(--hdh-red);
}
.table { --bs-table-color: var(--hdh-ink); font-size: var(--hdh-fs-sm); }
.table > thead th { background: var(--hdh-red); color: var(--hdh-on-red); }
.modal-content { --bs-modal-bg: var(--hdh-bg); --bs-modal-color: var(--hdh-ink); }
.shiny-output-error-validation { color: var(--hdh-err-fg); background: var(--hdh-bg-palered); font-size: var(--hdh-fs-base); padding: 12px 16px; border-radius: var(--hdh-radius); }

/* ==========================================================================
   匯東華元件（.hdh-*）— 不依賴 Bootstrap，靜態示意頁與 Shiny 共用
   ========================================================================== */
.hdh-app { font-family: var(--hdh-font); font-size: var(--hdh-fs-base); line-height: 1.7; color: var(--hdh-ink); background: var(--hdh-bg-page); margin: 0; min-height: 100vh; display: flex; flex-direction: column; }
.hdh-app > .hdh-main { flex: 1 0 auto; width: 100%; }
